record Product(String id, String name, Map<String, Object> attributes) {}

var product = new Product("P123", "Laptop", 
    Map.of("brand", "Dell", "ram", "16GB", "color", "silver"));
mongoTemplate.save(product); // each product can have different attributes

// Key-Value Store (Redis) - simple lookup
var sessionId = "user:12345:session";
redisTemplate.opsForValue().set(sessionId, userSessionData, Duration.ofMinutes(30));
var session = redisTemplate.opsForValue().get(sessionId); // fast cache retrieval

// Wide-Column Store (Cassandra) - time-series pattern
// CQL query for sensor data partitioned by device and time
var query = "SELECT temperature FROM sensor_readings " +
            "WHERE device_id = ? AND timestamp > ?";
var readings = cassandraTemplate.select(query, SensorReading.class, deviceId, startTime);

// Graph Database (Neo4j) - relationship queries
var cypher = "MATCH (u:User)-[:FOLLOWS]->(friend)-[:LIKES]->(p:Product) " +
             "WHERE u.id = $userId RETURN p"; // find products liked by friends
var recommendations = neo4jTemplate.query(cypher, Map.of("userId", userId));

