```javascript
// MongoDB: fetch a document, related data already embedded
db.users.findOne({ _id: 1 })
// -> { _id: 1, name: 'Asha', orders: [ { total: 250.0 } ] }
```

```sql
-- MySQL: the same result requires a join across normalized tables
SELECT u.name, o.total
FROM users u JOIN orders o ON o.user_id = u.id
WHERE u.id = 1;
```

MongoDB favors embedding for read speed and flexible structure; MySQL favors normalized tables with joins and strong integrity.

// Configuration in application.properties
// spring.data.redis.host=localhost
// spring.data.redis.port=6379

@Service
public class ProductService {
    private final ProductRepository productRepo;
    private final RedisTemplate<String, Product> redisTemplate;

    public Product getProduct(Long productId) {
        var cacheKey = "product:" + productId;

        // Try cache first - typically 1-2ms
        var cached = redisTemplate.opsForValue().get(cacheKey);
        if (cached != null) {
            return cached; // cache hit - avoid database
        }

        // Cache miss - query database (~20-50ms)
        var product = productRepo.findById(productId).orElseThrow();

        // Store in Redis with 5 minute expiration
        redisTemplate.opsForValue().set(cacheKey, product, Duration.ofMinutes(5));
        return product;
    }

    // Rate limiting with Redis
    public boolean allowRequest(String userId) {
        var key = "rate_limit:" + userId;
        var count = redisTemplate.opsForValue().increment(key);
        if (count == 1) {
            redisTemplate.expire(key, Duration.ofMinutes(1));
        }
        return count <= 100; // max 100 requests per minute
    }
}

// MongoDB allows different document structures in same collection
record UserV1(String id, String name, String email) {}
record UserV2(String id, String name, String email, String phoneNumber) {}
record UserV3(String id, String name, String email, Address address) {}
record Address(String street, String city, String zipCode) {}

// Insert documents with different shapes - no migration needed
mongoTemplate.save(new UserV1("u1", "Alice", "alice@example.com"));
mongoTemplate.save(new UserV2("u2", "Bob", "bob@example.com", "555-1234"));
var bobAddress = new Address("123 Main St", "Boston", "02101");
mongoTemplate.save(new UserV3("u3", "Carol", "carol@example.com", bobAddress));

// Query must handle missing fields
var users = mongoTemplate.findAll(Document.class, "users");
for (var user : users) {
    System.out.println(user.getString("name"));
    // phoneNumber might be null - application must handle gracefully
    var phone = user.getString("phoneNumber");
    if (phone != null) {
        System.out.println("Phone: " + phone);
    }
}

// Writing to DynamoDB - write succeeds immediately
var user = new User("user123", "John Doe", "john@example.com");
dynamoDbTemplate.save(user); // write to primary node returns success
System.out.println("User saved at: " + Instant.now());

// Reading immediately after write - might get stale data
var retrieved1 = dynamoDbTemplate.load(User.class, "user123"); 
// could return old data if read from replica not yet updated

// Eventually consistent read (default)
var eventualRead = dynamoDbTemplate.load(User.class, "user123");
System.out.println("Eventual read: " + eventualRead.getEmail());
// might still be old email

// Strongly consistent read (forces read from primary)
var options = new DynamoDbLoadOptions().withConsistentRead(true);
var strongRead = dynamoDbTemplate.load(User.class, "user123", options);
System.out.println("Strong read: " + strongRead.getEmail());
// guaranteed to return latest write, but higher latency

// In practice: most NoSQL read operations accept stale data for speed

// CP System (PostgreSQL with synchronous replication)
@Transactional
public void transferMoney(Long fromAccount, Long toAccount, BigDecimal amount) {
    var from = accountRepo.findById(fromAccount).orElseThrow();
    var to = accountRepo.findById(toAccount).orElseThrow();

    from.debit(amount); // if replica is down, this throws exception
    to.credit(amount);  // both operations atomic - CP guarantees consistency

    accountRepo.saveAll(List.of(from, to));
    // commit fails if synchronous replica unreachable - availability sacrificed
}

// AP System (Cassandra with quorum writes)
public void recordPageView(String userId, String pageId) {
    var view = new PageView(userId, pageId, Instant.now());
    cassandraTemplate.insert(view); // succeeds even if some nodes down
    // returns success immediately - availability maintained
    // consistency sacrificed - reads might not see this write for milliseconds
}

// The practical difference: CP fails fast maintaining correctness,
// AP stays responsive accepting temporary inconsistency
